from kit import *
CAT = "integration"
def GA(expr, var="x"): return ("anti", X(expr))
def ic(fam, expr, lines, expect, var="x", **kw):
    add(CAT, fam, iprob(expr, var), lines, expect, goal=GA(expr, var), var=var, **kw)
def NUM(v, closed=True): return ("num", ev(X(v), {}), closed)
def dic(fam, expr, lo, hi, lines, expect, val, var="x", **kw):
    add(CAT, fam, diprob(expr, lo, hi, var), lines, expect, goal=NUM(val), var=var, **kw)

